const j = $input.first().json || {};
const telegram_id = String(j.telegram_id == null ? '' : j.telegram_id).trim();
const chat_id = String(j.chat_id || telegram_id).trim();
let contact = null;
const raw = j.contact_json;
if (raw && typeof raw === 'object') { contact = raw; }
else if (raw && String(raw).trim()) { try { contact = JSON.parse(String(raw)); } catch (e) { contact = null; } }
return [{ json: {
  has_id: telegram_id.length > 0,
  telegram_id,
  chat_id,
  text: String(j.text == null ? '' : j.text).trim(),
  contact,
  update_id: String(j.update_id || ''),
  first_name: String(j.first_name || ''),
  username: String(j.username || ''),
} }];

const inp = $('Normalize Input').first().json;
const sessRows = $('Get Session').all().map(function (i) { return i.json; }).filter(function (r) { return r && r.telegram_id; });
const empRows = $('Get Employee Rows').all().map(function (i) { return i.json; }).filter(function (r) { return r && r.telegram_id; });
const setRows = $('Get Settings').all().map(function (i) { return i.json; }).filter(function (r) { return r && r.setting_key; });
const S = {};
setRows.forEach(function (r) { S[r.setting_key] = r.setting_value; });
function parseList(v) { try { const a = JSON.parse(v || '[]'); return Array.isArray(a) ? a.map(String) : []; } catch (e) { return []; } }
const positions = parseList(S.positions);
const departments = parseList(S.departments);
const tz = S.timezone || 'Asia/Almaty';
const now = DateTime.now().setZone(tz);
const nowIso = now.toISO();
const MAIN_MENU = [['🟢 Начать работу', '🔴 Завершить работу'], ['🐟 Fish Coins', '📊 Моя статистика'], ['🏖 Отпуск', '🤒 Больничный'], ['📅 Встреча', '👤 Мой профиль'], ['🤖 Спросить TUNA']];
const SCHEDULE_TYPES = ['5/2', '2/2', '6/1', 'Гибкий', 'Индивидуальный'];
const CONFIRM_BTN = '✅ Подтвердить';
const EDIT_BTN = '✏️ Изменить данные';
function chunk(arr, n) { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; }

function scheduleText(d) {
  const t = d.schedule_type || '';
  let s = t;
  if (d.schedule_start && d.schedule_end) s += ', ' + d.schedule_start + '–' + d.schedule_end + (d.schedule_overnight ? ' (ночная смена)' : '');
  if (d.first_work_date) s += ', первый рабочий день: ' + d.first_work_date;
  if (d.hours_per_day) s += ', ' + d.hours_per_day + ' ч/день';
  if (d.schedule_description) s += ', ' + d.schedule_description;
  return s;
}
function summary(d) {
  return [
    'Проверьте данные:',
    '👤 ФИО: ' + d.full_name,
    '💼 Должность: ' + d.position,
    '🏢 Отдел: ' + d.department,
    '🎂 Дата рождения: ' + d.birth_date + ' (' + d.age + ' лет)',
    '⚧ Пол: ' + (d.gender || 'не указан'),
    '📱 Телефон: ' + d.phone,
    '🗓 График: ' + scheduleText(d),
  ].join('\n');
}
function prompt(step, d) {
  switch (step) {
    case 'FULL_NAME': return { text: 'Введите ФИО: Фамилия Имя (отчество — по желанию).\nПример: Иванов Иван Иванович', keyboard_type: 'remove', keyboard: [] };
    case 'POSITION': return positions.length
      ? { text: 'Укажите вашу должность — выберите из списка или напишите свою.', keyboard_type: 'reply', keyboard: chunk(positions, 2) }
      : { text: 'Укажите вашу должность.', keyboard_type: 'remove', keyboard: [] };
    case 'DEPARTMENT': return departments.length
      ? { text: 'Выберите ваш отдел или напишите его название.', keyboard_type: 'reply', keyboard: chunk(departments, 2) }
      : { text: 'Укажите ваш отдел.', keyboard_type: 'remove', keyboard: [] };
    case 'BIRTH_DATE': return { text: 'Введите дату рождения в формате ДД.ММ.ГГГГ (например, 15.05.1995).', keyboard_type: 'remove', keyboard: [] };
    case 'GENDER': return { text: 'Укажите пол (необязательно).', keyboard_type: 'reply', keyboard: [['Мужской', 'Женский'], ['Пропустить']] };
    case 'PHONE': return { text: 'Нажмите кнопку «📱 Отправить номер телефона» ниже. Номер подтверждается через Telegram — вводить его вручную не нужно.', keyboard_type: 'contact', keyboard: [['📱 Отправить номер телефона']] };
    case 'SCHEDULE_TYPE': return { text: 'Выберите тип графика работы.', keyboard_type: 'reply', keyboard: [['5/2', '2/2', '6/1'], ['Гибкий', 'Индивидуальный']] };
    case 'SCHED_DESC': return { text: 'Опишите ваш индивидуальный график (например: пн, ср, пт).', keyboard_type: 'remove', keyboard: [] };
    case 'SCHED_TIME': return { text: 'Введите время начала и окончания смены в формате ЧЧ:ММ-ЧЧ:ММ (например, 09:00-18:00). Для ночной смены: 22:00-07:00.', keyboard_type: 'remove', keyboard: [] };
    case 'SCHED_FIRST_DATE': return { text: 'Введите дату первого рабочего дня цикла 2/2 в формате ДД.ММ.ГГГГ.', keyboard_type: 'remove', keyboard: [] };
    case 'SCHED_HOURS': return { text: 'Сколько часов в день вы планируете работать? Введите число от 1 до 24.', keyboard_type: 'remove', keyboard: [] };
    case 'CONFIRM': return { text: summary(d), keyboard_type: 'reply', keyboard: [[CONFIRM_BTN], [EDIT_BTN]] };
    default: return { text: 'Введите ФИО: Фамилия Имя (отчество — по желанию).', keyboard_type: 'remove', keyboard: [] };
  }
}
function parseDate(s) {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(s);
  if (!m) return null;
  const dt = DateTime.fromObject({ year: Number(m[3]), month: Number(m[2]), day: Number(m[1]) }, { zone: tz });
  return dt.isValid ? dt : null;
}
const L = 'A-Za-zА-Яа-яЁёӘәҒғҚқҢңӨөҰұҮүҺһІі';
const WORD = new RegExp('^[' + L + ']+(-[' + L + ']+)?$');
const TIME = /^([01]\d|2[0-3]):([0-5]\d)\s*[-–—]\s*([01]\d|2[0-3]):([0-5]\d)$/;

function handle(step, text, d) {
  const isCmd = text.charAt(0) === '/';
  switch (step) {
    case 'FULL_NAME': {
      const words = text.split(/\s+/).filter(Boolean);
      if (isCmd || words.length < 2 || words.length > 4 || !words.every(function (w) { return WORD.test(w); })) return { ok: false, error: 'ФИО должно содержать минимум фамилию и имя, только буквы и дефис.' };
      d.full_name = words.join(' ');
      return { ok: true, next: 'POSITION' };
    }
    case 'POSITION': {
      if (isCmd || text.length < 2 || text.length > 60) return { ok: false, error: 'Название должности должно быть от 2 до 60 символов.' };
      d.position = text;
      return { ok: true, next: 'DEPARTMENT' };
    }
    case 'DEPARTMENT': {
      if (isCmd || text.length < 2 || text.length > 60) return { ok: false, error: 'Название отдела должно быть от 2 до 60 символов.' };
      d.department = text;
      return { ok: true, next: 'BIRTH_DATE' };
    }
    case 'BIRTH_DATE': {
      const dt = parseDate(text);
      if (!dt) return { ok: false, error: 'Такой даты не существует или формат неверный. Нужен формат ДД.ММ.ГГГГ.' };
      if (dt > now) return { ok: false, error: 'Дата рождения не может быть в будущем.' };
      const age = Math.floor(now.diff(dt, 'years').years);
      if (age < 14 || age > 100) return { ok: false, error: 'Возраст должен быть от 14 до 100 лет (получилось ' + age + ').' };
      d.birth_date = dt.toFormat('dd.MM.yyyy');
      d.age = age;
      return { ok: true, next: 'GENDER' };
    }
    case 'GENDER': {
      if (text === 'Мужской' || text === 'Женский') d.gender = text;
      else if (text === 'Пропустить') d.gender = '';
      else return { ok: false, error: 'Выберите вариант кнопкой.' };
      return { ok: true, next: 'PHONE' };
    }
    case 'PHONE': {
      const c = inp.contact;
      if (!c || !c.phone_number) return { ok: false, error: 'Номер нужно отправить кнопкой, а не вводить вручную.' };
      if (String(c.user_id || '') !== String(inp.telegram_id)) return { ok: false, error: 'Этот контакт принадлежит другому человеку. Отправьте свой номер кнопкой ниже.' };
      let p = String(c.phone_number).replace(/[^\d+]/g, '');
      if (p.charAt(0) !== '+') p = '+' + p;
      d.phone = p;
      d.phone_verified = true;
      return { ok: true, next: 'SCHEDULE_TYPE' };
    }
    case 'SCHEDULE_TYPE': {
      if (SCHEDULE_TYPES.indexOf(text) < 0) return { ok: false, error: 'Выберите тип графика кнопкой.' };
      d.schedule_type = text;
      delete d.schedule_start; delete d.schedule_end; delete d.schedule_overnight; delete d.first_work_date; delete d.hours_per_day; delete d.schedule_description;
      if (text === 'Гибкий') return { ok: true, next: 'SCHED_HOURS' };
      if (text === 'Индивидуальный') return { ok: true, next: 'SCHED_DESC' };
      return { ok: true, next: 'SCHED_TIME' };
    }
    case 'SCHED_DESC': {
      if (isCmd || text.length < 3 || text.length > 200) return { ok: false, error: 'Описание должно быть от 3 до 200 символов.' };
      d.schedule_description = text;
      return { ok: true, next: 'SCHED_TIME' };
    }
    case 'SCHED_TIME': {
      const m = TIME.exec(text);
      if (!m) return { ok: false, error: 'Неверный формат времени. Пример: 09:00-18:00.' };
      const st = m[1] + ':' + m[2];
      const en = m[3] + ':' + m[4];
      if (st === en) return { ok: false, error: 'Время начала и окончания не должны совпадать.' };
      d.schedule_start = st;
      d.schedule_end = en;
      d.schedule_overnight = en < st;
      return { ok: true, next: d.schedule_type === '2/2' ? 'SCHED_FIRST_DATE' : 'CONFIRM' };
    }
    case 'SCHED_FIRST_DATE': {
      const dt = parseDate(text);
      if (!dt) return { ok: false, error: 'Такой даты не существует или формат неверный. Нужен формат ДД.ММ.ГГГГ.' };
      d.first_work_date = dt.toFormat('dd.MM.yyyy');
      return { ok: true, next: 'CONFIRM' };
    }
    case 'SCHED_HOURS': {
      const h = Number(text.replace(',', '.'));
      if (!Number.isFinite(h) || h < 1 || h > 24) return { ok: false, error: 'Введите число от 1 до 24.' };
      d.hours_per_day = h;
      return { ok: true, next: 'CONFIRM' };
    }
    case 'CONFIRM': {
      if (text === CONFIRM_BTN) return { ok: true, finalize: true };
      if (text === EDIT_BTN) return { ok: true, reset: true, next: 'FULL_NAME' };
      return { ok: false, error: 'Нажмите «' + CONFIRM_BTN + '» или «' + EDIT_BTN + '».' };
    }
    default:
      return { ok: true, next: 'FULL_NAME' };
  }
}

function makeReply(p, extra) {
  return Object.assign({ action: 'REPLY', chat_id: inp.chat_id, text: p.text, keyboard_type: p.keyboard_type, keyboard: p.keyboard, registration_complete: false, employee_id: null, tuna_id: null, welcome_bonus_result: null }, extra || {});
}

const active = empRows.find(function (r) { return String(r.employee_status || '').toUpperCase() === 'ACTIVE'; });
const welcomeAlready = empRows.some(function (r) { return r.welcome_bonus_granted === true || String(r.welcome_bonus_granted) === 'true'; });
const sess = sessRows[0];
if (active && sess) {
  // Профиль уже создан, но регистрация не была завершена (сбой после записи профиля).
  // Безопасно доводим до конца: без нового профиля и нового TUNA-ID; бонус идемпотентен.
  return [{ json: {
    op: 'FINALIZE', existing: true,
    existing_employee_id: active.employee_id, existing_tuna_id: active.tuna_id,
    telegram_id: inp.telegram_id, chat_id: inp.chat_id, draft: (function () { try { return JSON.parse(sess.draft_json || '{}') || {}; } catch (e) { return {}; } })(),
    counter: S.tuna_id_counter || '0', welcome_already: welcomeAlready,
    timezone: tz, now_iso: nowIso, main_menu: MAIN_MENU,
  } }];
}
if (active) {
  const prof = ['✅ Вы уже зарегистрированы.', '🆔 ID: ' + active.tuna_id, '👤 ' + (active.full_name || ''), '💼 ' + (active.position || '') + ' · ' + (active.department || ''), '🐟 Fish Coins: ' + (active.fish_coins_balance == null ? 0 : active.fish_coins_balance)].join('\n');
  return [{ json: { op: 'REPLY_ONLY', reply: makeReply({ text: prof + '\n\nВыберите действие в меню ниже.', keyboard_type: 'main_menu', keyboard: MAIN_MENU }, { registration_complete: true, employee_id: active.employee_id, tuna_id: active.tuna_id, result: 'ALREADY_REGISTERED' }) } }];
}
function missingStep(d) {
  if (!d.full_name) return 'FULL_NAME';
  if (!d.position) return 'POSITION';
  if (!d.department) return 'DEPARTMENT';
  if (!d.birth_date) return 'BIRTH_DATE';
  if (!d.phone || !d.phone_verified) return 'PHONE';
  const t = d.schedule_type;
  if (SCHEDULE_TYPES.indexOf(t) < 0) return 'SCHEDULE_TYPE';
  if (t === 'Гибкий') return d.hours_per_day ? null : 'SCHED_HOURS';
  if (t === 'Индивидуальный' && !d.schedule_description) return 'SCHED_DESC';
  if (!d.schedule_start || !d.schedule_end) return 'SCHED_TIME';
  if (t === '2/2' && !d.first_work_date) return 'SCHED_FIRST_DATE';
  return null;
}

let step;
let draft = {};
let startedAt = nowIso;
let text = '';
let resultCode = 'STEP';

if (!sess) {
  step = 'FULL_NAME';
  text = 'Добро пожаловать в TUNA HR! Давайте зарегистрируемся — это займёт пару минут.\n\n' + prompt(step, draft).text;
  resultCode = 'STARTED';
} else {
  step = sess.step || 'FULL_NAME';
  try { draft = JSON.parse(sess.draft_json || '{}') || {}; } catch (e) { draft = {}; }
  startedAt = sess.started_at || nowIso;
  const t = inp.text;
  if ((t === '/start' || t === '/register') && !inp.contact) {
    text = 'Продолжаем регистрацию с того места, где вы остановились.\n\n' + prompt(step, draft).text;
    resultCode = 'RESUMED';
  } else {
    const r = handle(step, t, draft);
    if (!r.ok) {
      text = '⚠️ ' + r.error + '\n\n' + prompt(step, draft).text;
      resultCode = 'INVALID_INPUT';
    } else if (r.finalize && missingStep(draft)) {
      step = missingStep(draft);
      text = '⚠️ В анкете не хватает данных. Заполните, пожалуйста, этот пункт.\n\n' + prompt(step, draft).text;
      resultCode = 'INCOMPLETE_DRAFT';
    } else if (r.finalize) {
      return [{ json: {
        existing: false,
        op: 'FINALIZE',
        telegram_id: inp.telegram_id,
        chat_id: inp.chat_id,
        draft,
        counter: S.tuna_id_counter || '0',
        welcome_already: welcomeAlready,
        timezone: tz,
        now_iso: nowIso,
        main_menu: MAIN_MENU,
      } }];
    } else {
      if (r.reset) { draft = {}; text = 'Хорошо, заполним данные заново.\n\n'; resultCode = 'EDIT'; }
      step = r.next;
      text += prompt(step, draft).text;
    }
  }
}

const p = prompt(step, draft);
return [{ json: {
  op: 'SAVE_SESSION',
  telegram_id: inp.telegram_id,
  step,
  draft_json: JSON.stringify(draft),
  started_at: startedAt,
  last_activity: nowIso,
  reply: makeReply({ text, keyboard_type: p.keyboard_type, keyboard: p.keyboard }, { result: resultCode, step }),
} }];

function uuidv4() { const h = '0123456789abcdef'; let s = ''; for (let i = 0; i < 36; i++) { if (i === 8 || i === 13 || i === 18 || i === 23) { s += '-'; continue; } if (i === 14) { s += '4'; continue; } let r = Math.floor(Math.random() * 16); if (i === 19) r = (r & 3) | 8; s += h[r]; } return s; }
const d = $('Process Step').first().json;
const draft = d.draft || {};
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.tuna_id; });
const taken = new Set(rows.map(function (r) { return String(r.tuna_id); }));
let counter = parseInt(String(d.counter || '0'), 10);
if (!Number.isFinite(counter) || counter < 0) counter = 0;
// Counter is not atomic: also respect the highest ID already stored and skip any taken number.
rows.forEach(function (r) { const m = /^TUNA-(\d+)$/.exec(String(r.tuna_id)); if (m) counter = Math.max(counter, parseInt(m[1], 10)); });
function fmt(n) { return 'TUNA-' + String(n).padStart(6, '0'); }
let n = counter + 1;
while (taken.has(fmt(n))) n++;
const scheduleConfig = {
  type: draft.schedule_type || '',
  start: draft.schedule_start || null,
  end: draft.schedule_end || null,
  overnight: !!draft.schedule_overnight,
  first_work_date: draft.first_work_date || null,
  hours_per_day: draft.hours_per_day || null,
  description: draft.schedule_description || null,
  timezone: d.timezone,
};
const isNew = !d.existing;
return [{ json: {
  is_new: isNew,
  employee_id: isNew ? uuidv4() : String(d.existing_employee_id),
  tuna_id: isNew ? fmt(n) : String(d.existing_tuna_id),
  new_counter: isNew ? String(n) : String(counter),
  telegram_id: d.telegram_id,
  chat_id: d.chat_id,
  full_name: draft.full_name || '',
  position: draft.position || '',
  department: draft.department || '',
  birth_date: draft.birth_date || '',
  gender: draft.gender || '',
  phone: draft.phone || '',
  schedule_type: draft.schedule_type || '',
  schedule_config: JSON.stringify(scheduleConfig),
  schedule_id: uuidv4(),
  registered_at: d.now_iso,
  welcome_already: !!d.welcome_already,
  grant_welcome: !d.welcome_already,
  main_menu: d.main_menu,
} }];

const g = $('Generate Identity').first().json;
let w = null;
try { w = $('Call Welcome Ledger').first().json; } catch (e) { w = null; }
let bonusText = '';
let bonus = null;
if (w) {
  bonus = { ok: w.ok, result: w.result, applied_amount: w.applied_amount, balance_after: w.balance_after, transaction_id: w.transaction_id };
  if (w.result === 'APPLIED') bonusText = '\n\n🐟 Приветственный бонус: +1 Fish Coin. Баланс: ' + w.balance_after + '.';
  else if (w.result === 'DUPLICATE') bonusText = '\n\nПриветственный бонус уже был начислен ранее.';
  else bonusText = '\n\nПриветственный бонус не начислен (' + w.result + ').';
} else {
  bonus = { ok: true, result: 'SKIPPED_ALREADY_GRANTED', applied_amount: 0 };
  bonusText = '\n\nПриветственный бонус уже был начислен ранее.';
}
return [{ json: {
  action: 'REPLY',
  chat_id: g.chat_id,
  text: '✅ Регистрация завершена!\nВаш ID: ' + g.tuna_id + bonusText + '\n\nВыберите действие в меню ниже.',
  keyboard_type: 'main_menu',
  keyboard: g.main_menu,
  registration_complete: true,
  employee_id: g.employee_id,
  tuna_id: g.tuna_id,
  welcome_bonus_result: bonus,
  result: 'REGISTERED',
} }];

// Диагностика сбоя регистрации. Без персональных данных анкеты (ФИО, телефон, дата рождения).
const j = $input.first().json || {};
const e = j.error;
let message = '';
let type = 'Error';
if (e && typeof e === 'object') { message = String(e.message || e.description || JSON.stringify(e)); type = String(e.name || e.type || 'Error'); }
else if (e) { message = String(e); }
else { message = String(j.message || 'unknown error'); }
const m = /(\w*Error)\b/.exec(message);
if (m) type = m[1];
let tg = '';
try { tg = String($('Normalize Input').first().json.telegram_id || ''); } catch (x) { tg = ''; }
let chat = tg;
try { chat = String($('Normalize Input').first().json.chat_id || tg); } catch (x) {}
const node = String($prevNode && $prevNode.name ? $prevNode.name : 'unknown');
const STAGES = { 'Generate Identity': 'GENERATE_ID', 'Insert Employee': 'SAVE_PROFILE', 'Insert Schedule': 'SAVE_SCHEDULE', 'Update ID Counter': 'UPDATE_COUNTER', 'Call Welcome Ledger': 'WELCOME_BONUS', 'Close Session': 'CLEAR_SESSION' };
return [{ json: {
  workflow_name: 'TUNA – Registration',
  node_name: node,
  stage: STAGES[node] || 'FINALIZE',
  error_type: type.slice(0, 80),
  error_message: message.replace(/\+?\d[\d\s()-]{8,}\d/g, '[phone]').slice(0, 500),
  telegram_id: tg,
  chat_id: chat,
  execution_id: String($execution.id),
  occurred_at: DateTime.now().setZone('Asia/Almaty').toISO(),
} }];
